contracts/CommodityToken/CommodityToken..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC20PermitUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

interface ICommodityTokenProxy {
    function getImplementation() external view returns (address);
}

/*
    @title CommodityToken
    @dev ERC20 Token representing real-asset backed token with upgradeability, access control, pausing, and freezing features.
 */
contract CommodityToken is
    Initializable,
    UUPSUpgradeable,
    ERC20PermitUpgradeable,
    AccessControlUpgradeable,
    PausableUpgradeable
{
    // ====================
    // Roles
    // ====================
    // @notice Default admin role for AccessControl is Declared in AccessControlUpgradeable : 0x00
    // @notice UPGRADER_ROLE is used when upgrading the authorized implementation
    // 0x189ab7a9244df0848122154315af71fe140f3db0fe014031783b0946b8c9d2e3;
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    // @notice PAUSER_ROLE is used to pause and unpause the contract
    // 0x65d7a28e3265b37a6474929f336521b332c1681b933f6cb9f3376673440d862a;
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    // @notice VAULT_MINTER_ROLE is used to mint tokens(backed by vault assets)
    // 0x98e4415ac43dc65a73fb377c77c834c9fba44fb3f81dc603d1f33e6023519e07;
    bytes32 public constant VAULT_MINTER_ROLE = keccak256("VAULT_MINTER_ROLE");

    // @notice MINTER_ROLE is used to mint tokens(usually for bridge minting)
    // 0x9f2df0fed2c77648de5860a4cc508cd0818c85b8b8a1ab4ceeef8d981c8956a6;
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    // @notice BURNER_ROLE is used to burn tokens
    // 0x3c11d16cbaffd01df69ce1c404f6340ee057498f5f00246190ea54220576a848;
    bytes32 public constant BURNER_ROLE = keccak256("BURNER_ROLE");

    // @notice RISK_MANAGER_ROLE is used to manage risk-related functions
    // 0xb2e3ee861706f0756afea8a5257301f83561f9ac10b8f43b771dc928566f8c61;
    bytes32 public constant RISK_MANAGER_ROLE = keccak256("RISK_MANAGER_ROLE");

    // @notice FROZEN_ROLE is used to identify frozen accounts
    // @notice only RISK_MANAGER_ROLE can add/remove accounts to/from this role
    // @notice Users can self-assign FROZEN_ROLE via selfFreeze() without RISK_MANAGER_ROLE
    // 0x692fe418ed64ac7ff16f79ea7dade91c969e167ccb96f56f1a4cc50061b6005c;
    bytes32 public constant FROZEN_ROLE = keccak256("FROZEN_ROLE");

    // @notice MINT_APPROVER_ROLE is used to make signature for mint approvals
    // 0x729e7093b317e8cb328751b2fec56d2c53d4821956f473a16b7334aeb4bd61bd;
    bytes32 public constant MINT_APPROVER_ROLE =
        keccak256("MINT_APPROVER_ROLE");
    // @notice UPGRADE_AUDITOR_ROLE is used to audit and confirm new implementation
    // 0x518cb1580b90d89361b4998d16c498d3d1e93d39fec155f2214eee68154fb72e;
    bytes32 public constant UPGRADE_AUDITOR_ROLE =
        keccak256("UPGRADE_AUDITOR_ROLE");

    // ====================
    // Initializer
    // ====================
    function initialize(
        address initialAdmin,
        string memory _name,
        string memory _symbol
    ) public initializer onlyProxy {
        require(
            initialAdmin != address(0),
            "CommodityToken: initial admin is zero"
        );
        __ERC20_init(_name, _symbol);

        // including initialize EIP712 domain separator
        __ERC20Permit_init(_name);
        __AccessControl_init();
        __Pausable_init();

        // Grant Admin role to the initial admin
        _grantRole(DEFAULT_ADMIN_ROLE, initialAdmin);

        // RISK_MANAGER_ROLE can manage FROZEN_ROLE
        _setRoleAdmin(FROZEN_ROLE, RISK_MANAGER_ROLE);
    }

    // ====================
    // UUPS Authorization
    // ====================
    // @dev _authorizeUpgrade function here is commented because the function is overridden later with additional checks.
    // function _authorizeUpgrade(
    //     address newImplementation
    // ) internal override onlyProxy onlyRole(UPGRADER_ROLE) {}

    // ====================
    // Pause Functions
    // ====================
    // @notice Pause all token transfers and approvals
    // @dev Only accounts with the PAUSER_ROLE can call this function
    function pause() external onlyProxy onlyRole(PAUSER_ROLE) {
        _pause();
    }

    // @notice Unpause all token transfers and approvals
    // @dev Only accounts with the PAUSER_ROLE can call this function
    function unpause() external onlyProxy onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    // ====================
    // Risk Manager Functions
    // ====================
    function freeze(address _account) external onlyProxy {
        grantRole(FROZEN_ROLE, _account); // Permission validation is implemented in grantRole function
    }

    function unfreeze(address _account) external onlyProxy {
        revokeRole(FROZEN_ROLE, _account); // Permission validation is implemented in revokeRole function
    }

    // @notice Users can self-assign FROZEN_ROLE via selfFreeze() without RISK_MANAGER_ROLE
    function selfFreeze() external onlyProxy {
        _grantRole(FROZEN_ROLE, _msgSender());
    }

    error AccountNotFrozen(address account);
    // @notice Wipe the balance of a frozen account and reset allowances
    // @notice Only allowances with the frozen account as the owner are reset, allowances with the frozen account as the spender are not affected
    function wipeFrozenAccount(
        address _account
    ) external onlyProxy onlyRole(RISK_MANAGER_ROLE) {
        if (!isFrozen(_account)) {
            revert AccountNotFrozen(_account);
        }
        uint256 frozenBalance = balanceOf(_account);
        _updateForWipe(_account, frozenBalance);

        // After wiping the frozen account, nonce for allowances should be increased to reset all allowances
        _increaseAllowanceNonce(_account);

        emit Wiped(_account, frozenBalance);
    }

    function isFrozen(address _account) public view returns (bool) {
        return hasRole(FROZEN_ROLE, _account);
    }

    error InvalidRenounceAttempt();
    function renounceRole(
        bytes32 role,
        address callerConfirmation
    ) public override onlyProxy {
        if (role == FROZEN_ROLE) {
            revert InvalidRenounceAttempt();
        }
        if (role == DEFAULT_ADMIN_ROLE) {
            revert InvalidRenounceAttempt();
        }
        super.renounceRole(role, callerConfirmation);
    }

    error AccountFrozen(address account);

    // ====================
    // Update ERC20 Hook
    // ====================
    function _update(
        address _from,
        address _to,
        uint256 _amount
    ) internal override whenNotPaused onlyProxy {
        if (isFrozen(_from)) {
            revert AccountFrozen(_from);
        }
        if (isFrozen(_to)) {
            revert AccountFrozen(_to);
        }

        super._update(_from, _to, _amount);
    }

    // @notice Internal function to update balances when wiping a frozen account
    // @notice normal _update function does not work when the account is frozen
    function _updateForWipe(
        address _account,
        uint256 _amount
    ) internal onlyProxy {
        super._update(_account, address(0), _amount);
    }

    // ====================
    // Nonce Authorization (EIP712)
    // ====================
    // keccak256(abi.encode(uint256(keccak256(bytes("EIP712.USED_NONCE"))) - 1)) & ~bytes32(uint256(0xff));
    bytes32 private constant AUTHORIZATION_STATE_STORAGE =
        0xaedccaaf8ccffebfb1c1fab02788f133cca08385faadbe1e213b04d3cebadd00;

    struct AuthorizationStorage {
        mapping(address => mapping(bytes32 => bool)) usedNonces;
    }

    function _getUsedNoncesStorage()
        internal
        pure
        returns (AuthorizationStorage storage store)
    {
        bytes32 slot = AUTHORIZATION_STATE_STORAGE;
        assembly {
            store.slot := slot
        }
    }

    function authorizationState(
        address authorizer,
        bytes32 nonce
    ) external view returns (bool) {
        AuthorizationStorage storage store = _getUsedNoncesStorage();
        return store.usedNonces[authorizer][nonce];
    }

    function cancelAuthorization(
        address authorizer,
        bytes32 nonce,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external onlyProxy {
        AuthorizationStorage storage store = _getUsedNoncesStorage();
        if (store.usedNonces[authorizer][nonce] == true) {
            revert InvalidAuthorization(authorizer, nonce);
        }

        // Verify Signature
        bytes32 structHash = keccak256(
            abi.encode(
                keccak256(
                    "CancelAuthorization(address authorizer,bytes32 nonce)"
                ),
                authorizer,
                nonce
            )
        );

        bytes32 hash = _hashTypedDataV4(structHash);
        address signer = ECDSA.recover(hash, v, r, s);

        if (signer != authorizer) {
            revert InvalidSignature();
        }

        // Mark the nonce as used to prevent future use
        store.usedNonces[authorizer][nonce] = true;
        emit AuthorizationCancelled(authorizer, nonce);
    }

    error InvalidAuthorization(address authorizer, bytes32 nonce);

    // ====================
    // ERC20 Functions(Permissioned)
    // ====================
    function mint(
        address _to,
        uint256 _amount
    ) external onlyRole(MINTER_ROLE) onlyProxy {
        _mint(_to, _amount);
        emit Minted(_to, _amount);
    }

    function burn(uint256 _amount) external onlyRole(BURNER_ROLE) onlyProxy {
        _burn(_msgSender(), _amount);
        emit Burned(_msgSender(), _amount);
    }

    // ====================
    // Approved Mint
    // ====================

    error AuthorizationExpired(
        uint256 validAfter,
        uint256 validBefore,
        uint256 currentTime
    );
    error InvalidTimeframe(uint256 validAfter, uint256 validBefore);
    error InvalidSignature();

    function mintWithAuthorization(
        address to,
        uint256 amount,
        bytes32 nonce,
        uint256 validAfter,
        uint256 validBefore,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external onlyRole(VAULT_MINTER_ROLE) onlyProxy {
        // Check time validity
        if (validAfter > validBefore) {
            revert InvalidTimeframe(validAfter, validBefore);
        }
        if (block.timestamp <= validAfter || block.timestamp >= validBefore) {
            revert AuthorizationExpired(
                validAfter,
                validBefore,
                block.timestamp
            );
        }

        // Verify Signature
        // if parameters are different from those signed data, ECDSA.recover will return a different address
        bytes32 structHash = keccak256(
            abi.encode(
                keccak256(
                    "MintWithAuthorization(address to,uint256 amount,bytes32 nonce,uint256 validAfter,uint256 validBefore)"
                ),
                to,
                amount,
                nonce,
                validAfter,
                validBefore
            )
        );

        bytes32 hash = _hashTypedDataV4(structHash);
        address signer = ECDSA.recover(hash, v, r, s);

        if (signer == address(0) || !hasRole(MINT_APPROVER_ROLE, signer)) {
            revert InvalidSignature();
        }

        // Check nonce validity
        AuthorizationStorage storage store = _getUsedNoncesStorage();
        if (store.usedNonces[signer][nonce]) {
            revert InvalidAuthorization(signer, nonce);
        }

        // Available when signer == approver && msg.sender == MINTER_ROLE
        _mint(to, amount);
        emit Minted(to, amount);

        // Mark the nonce as used
        store.usedNonces[signer][nonce] = true;
        emit AuthorizationUsed(msg.sender, signer, nonce);
    }

    // ====================
    // ERC20 Functions(Public)
    // ====================
    function name() public view override returns (string memory) {
        return super.name();
    }

    function symbol() public view override returns (string memory) {
        return super.symbol();
    }

    function decimals() public view override returns (uint8) {
        return super.decimals();
    }

    function _approve(
        address _owner,
        address _spender,
        uint256 _amount,
        bool emitEvent
    ) internal override onlyProxy {
        // When amount is zero, it means the approval is being revoked, so we allow it even when paused
        // For any non-zero approval, the contract must not be paused
        if (_amount > 0) {
            _requireNotPaused();

            // Frozen Accounts must not be able to approve and to be approved
            // Revoking approvals is allowed even the account is frozen
            if (isFrozen(_owner)) {
                revert AccountFrozen(_owner);
            }
            if (isFrozen(_spender)) {
                revert AccountFrozen(_spender);
            }
        }

        if (_owner == address(0)) {
            revert ERC20InvalidApprover(address(0));
        }
        if (_spender == address(0)) {
            revert ERC20InvalidSpender(address(0));
        }

        AllowanceNonceStorage
            storage allowanceStorage = _getAllowanceNonceStorage();
        uint256 currentNonce = allowanceStorage.nonce[_owner];
        allowanceStorage.allowance[_owner][currentNonce][_spender] = _amount;

        if (emitEvent) {
            emit Approval(_owner, _spender, _amount);
        }
    }

    function balanceOf(
        address _account
    ) public view override returns (uint256) {
        return super.balanceOf(_account);
    }

    function totalSupply() public view override returns (uint256) {
        return super.totalSupply();
    }

    // When a frozen account is wiped, allowances are being reset
    // Allowance : address user => uint256 nonce => address spender => uint256 amount
    struct AllowanceNonceStorage {
        mapping(address => uint256) nonce;
        mapping(address => mapping(uint256 => mapping(address => uint256))) allowance;
    }

    // allowanceNonceStorage slot
    // keccak256(abi.encode(uint256(keccak256(bytes("ALLOWANCE_NONCE_STORAGE"))) - 1)) & ~bytes32(uint256(0xff));
    bytes32 private constant allowanceNonceStorage =
        0xea41d1798cd34728e904635e32c4b899afc3c827783776b2bfabce68dbf12100;

    function _getAllowanceNonceStorage()
        private
        pure
        returns (AllowanceNonceStorage storage store)
    {
        assembly {
            store.slot := allowanceNonceStorage
        }
    }

    function _increaseAllowanceNonce(address _owner) internal {
        AllowanceNonceStorage
            storage allowanceStorage = _getAllowanceNonceStorage();
        allowanceStorage.nonce[_owner]++;
    }

    function allowance(
        address _owner,
        address _spender
    ) public view override returns (uint256) {
        AllowanceNonceStorage
            storage allowanceStorage = _getAllowanceNonceStorage();

        uint256 currentNonce = allowanceStorage.nonce[_owner];

        return allowanceStorage.allowance[_owner][currentNonce][_spender];
    }

    function transfer(
        address to,
        uint256 value
    ) public override whenNotPaused onlyProxy returns (bool) {
        super.transfer(to, value);
        return true;
    }

    function transferFrom(
        address from,
        address to,
        uint256 value
    ) public override whenNotPaused onlyProxy returns (bool) {
        if (isFrozen(_msgSender())) revert AccountFrozen(_msgSender());

        super.transferFrom(from, to, value);
        return true;
    }

    // ====================
    // UpgradeAuditor functions
    // ====================
    // @notice auditedImpl storage slot
    // keccak256(abi.encode(uint256(keccak256(bytes("AUDITED_IMPL"))) - 1)) & ~bytes32(uint256(0xff));
    bytes32 private constant AUDITED_IMPL =
        0x3b37ab6d30949955efc7d48c8e307e07fbeac94d91117e502bd889402f542100;

    function _getAuditedImplData()
        internal
        pure
        returns (AuditedImpl storage data)
    {
        assembly {
            data.slot := AUDITED_IMPL
        }
    }

    function getAuditedImplData() external pure returns (AuditedImpl memory) {
        AuditedImpl storage data = _getAuditedImplData();
        return data;
    }

    modifier isValidUpgrade(address _newImpl) {
        AuditedImpl storage data = _getAuditedImplData();
        if (
            _newImpl == address(0) ||
            _newImpl.code.length == 0 ||
            data.auditedImpl != _newImpl ||
            data.isUpgraded == true
        ) {
            revert InvalidImplementation(_newImpl);
        }

        // msg.sender == upgrader is already validated by onlyRole(UPGRADER_ROLE)
        // Upgrader should different from the auditor who confirmed the implementation
        if (data.auditor == msg.sender) {
            revert InvalidUpgrader();
        }

        if (
            data.validBefore < block.timestamp ||
            data.validAfter > block.timestamp
        ) {
            revert InvalidTimeframe(data.validAfter, data.validBefore);
        }

        _;
    }

    function upgradeToAndCall(
        address newImplementation,
        bytes memory data
    ) public payable override onlyProxy {
        super.upgradeToAndCall(newImplementation, data);

        // After successful upgrade, mark the audited implementation as upgraded to prevent reuse
        AuditedImpl storage auditedImplData = _getAuditedImplData();
        auditedImplData.isUpgraded = true;
    }

    // When upgrader is trying to upgrade without auditing, it will revert
    error InvalidImplementation(address implementation);
    error InvalidUpgrader();

    function _authorizeUpgrade(
        address _newImplementation
    )
        internal
        override
        onlyProxy
        onlyRole(UPGRADER_ROLE)
        isValidUpgrade(_newImplementation)
    {}

    // @notice Update the audited implementation address
    // @dev Only accounts with the UPGRADE_AUDITOR_ROLE can call this function
    // @dev This function allows the upgrade auditor to set the address of the audited implementation contract.
    // @dev This function is not including Updating the implementation itself, only setting the audited address.
    event AuditedImplUpdated(address oldAuditedImpl, address newAuditedImpl);

    struct AuditedImpl {
        address auditedImpl;
        address auditor;
        uint256 validAfter;
        uint256 validBefore;
        bool isUpgraded;
    }

    function updateAuditedImpl(
        address _newImpl
    ) external onlyProxy onlyRole(UPGRADE_AUDITOR_ROLE) {
        AuditedImpl storage oldAuditedImpl = _getAuditedImplData();

        // @notice _newImpl should not be zero address and should be different from current implementation to prevent setting the same implementation again
        if (
            _newImpl == address(0) ||
            ICommodityTokenProxy(address(this)).getImplementation() ==
            _newImpl ||
            _newImpl.code.length == 0
        ) {
            revert InvalidImplementation(_newImpl);
        }

        address oldImpl = oldAuditedImpl.auditedImpl;
        uint256 curBlockTimestamp = block.timestamp;

        oldAuditedImpl.auditedImpl = _newImpl;
        oldAuditedImpl.auditor = msg.sender;
        oldAuditedImpl.validAfter = curBlockTimestamp;
        oldAuditedImpl.validBefore = curBlockTimestamp + 3 days; // Valid for 3 days(72hours) after being set as audited implementation
        oldAuditedImpl.isUpgraded = false;

        emit AuditedImplUpdated(oldImpl, _newImpl);
    }

    // ====================
    // EIP3009
    // ====================

    // 0x7c7c6cdb67a18743f49ec6fa9b35f50d52ed05cbed4cc592e13b44501c1a2267;
    bytes32 public constant TRANSFER_WITH_AUTHORIZATION_TYPEHASH =
        keccak256(
            "TransferWithAuthorization(address from,address to,uint256 value,uint256 validAfter,uint256 validBefore,bytes32 nonce)"
        );

    // 0xd099cc98ef71107a616c4f0f941f04c322d8e254fe26b3c6668db87aae413de8;
    bytes32 public constant RECEIVE_WITH_AUTHORIZATION_TYPEHASH =
        keccak256(
            "ReceiveWithAuthorization(address from,address to,uint256 value,uint256 validAfter,uint256 validBefore,bytes32 nonce)"
        );

    function transferWithAuthorization(
        address from,
        address to,
        uint256 value,
        uint256 validAfter,
        uint256 validBefore,
        bytes32 nonce,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external whenNotPaused onlyProxy {
        // check time validity
        if (validAfter > validBefore) {
            revert InvalidTimeframe(validAfter, validBefore);
        }
        if (block.timestamp <= validAfter || block.timestamp >= validBefore) {
            revert AuthorizationExpired(
                validAfter,
                validBefore,
                block.timestamp
            );
        }

        AuthorizationStorage storage store = _getUsedNoncesStorage();
        // check nonce validity
        if (store.usedNonces[from][nonce]) {
            revert InvalidAuthorization(from, nonce);
        }

        // Verify Signature
        bytes32 structHash = keccak256(
            abi.encode(
                TRANSFER_WITH_AUTHORIZATION_TYPEHASH,
                from,
                to,
                value,
                validAfter,
                validBefore,
                nonce
            )
        );

        bytes32 hash = _hashTypedDataV4(structHash);
        address signer = ECDSA.recover(hash, v, r, s);

        if (signer != from) {
            revert InvalidSignature();
        }

        // Mark the nonce as used
        store.usedNonces[from][nonce] = true;
        emit AuthorizationUsed(msg.sender, signer, nonce);

        _transfer(from, to, value);
    }

    error CallerIsNotRecipient();
    function receiveWithAuthorization(
        address from,
        address to,
        uint256 value,
        uint256 validAfter,
        uint256 validBefore,
        bytes32 nonce,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external whenNotPaused onlyProxy {
        // check if msg.sender is the recipient
        if (to != msg.sender) {
            revert CallerIsNotRecipient();
        }

        // check time validity
        if (validAfter > validBefore) {
            revert InvalidTimeframe(validAfter, validBefore);
        }
        if (block.timestamp <= validAfter || block.timestamp >= validBefore) {
            revert AuthorizationExpired(
                validAfter,
                validBefore,
                block.timestamp
            );
        }

        AuthorizationStorage storage store = _getUsedNoncesStorage();
        // check nonce validity
        if (store.usedNonces[from][nonce]) {
            revert InvalidAuthorization(from, nonce);
        }

        // Verify Signature
        bytes32 structHash = keccak256(
            abi.encode(
                RECEIVE_WITH_AUTHORIZATION_TYPEHASH,
                from,
                to,
                value,
                validAfter,
                validBefore,
                nonce
            )
        );

        bytes32 hash = _hashTypedDataV4(structHash);
        address signer = ECDSA.recover(hash, v, r, s);

        if (signer != from) {
            revert InvalidSignature();
        }

        // Mark the nonce as used
        store.usedNonces[from][nonce] = true;
        emit AuthorizationUsed(msg.sender, signer, nonce);

        _transfer(from, to, value);
    }

    // ====================
    // Events
    // ====================
    event Minted(address indexed to, uint256 amount);
    event Burned(address indexed from, uint256 amount);
    event Wiped(address indexed account, uint256 amount);
    event AuthorizationUsed(
        address indexed msgSender,
        address indexed authorizer,
        bytes32 indexed nonce
    );
    event AuthorizationCancelled(
        address indexed authorizer,
        bytes32 indexed nonce
    );
}

contracts/CommodityToken/CommodityTokenP.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/proxy/Proxy.sol";

contract CommodityTokenProxy is Proxy {
    // ====================
    // EIP-1967 Slots
    // ====================
    // bytes32(uint256(keccak256('eip1967.proxy.implementation')) - 1)
    bytes32 private constant _IMPLEMENTATION_SLOT =
        0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    // ====================
    // Constructor
    // ====================
    /// @param _logic initial implementation contract address
    /// @param _data  call data for initialization
    constructor(address _logic, bytes memory _data) payable {
        require(_logic != address(0), "UUPSProxy: logic is zero");
        _setImplementation(_logic);

        if (_data.length > 0) {
            // Call the initialization function
            (bool success, ) = _logic.delegatecall(_data);
            require(success, "UUPSProxy: initialization failed");
        }
    }

    // ====================
    // EIP-1967 Functions
    // ====================
    function _getImplementation() internal view returns (address impl) {
        bytes32 slot = _IMPLEMENTATION_SLOT;
        assembly {
            impl := sload(slot)
        }
    }

    function _setImplementation(address newImplementation) private {
        bytes32 slot = _IMPLEMENTATION_SLOT;
        require(
            newImplementation.code.length > 0,
            "UUPSProxy: new implementation has no code"
        );
        assembly {
            sstore(slot, newImplementation)
        }
    }

    function _implementation() internal view override returns (address) {
        return _getImplementation();
    }

    function getImplementation() external view returns (address impl) {
        return _getImplementation();
    }

    // ====================
    // Receive
    // ====================
    receive() external payable {
        super._fallback();
    }
}

contracts/CommodityTokenIssuer/Commodity.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {
    SafeERC20
} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {
    IERC20Metadata
} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {
    IERC20Permit
} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";

import {
    ReentrancyGuard
} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

contract CommodityTokenIssuer is AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);

        _setRoleAdmin(WHITELISTED_ROLE, OPERATION_MANAGER_ROLE);
    }

    // ====================
    // Pair availability
    // ====================
    bool public areAllPairsAvailable = false;

    mapping(bytes32 => bool) public availablePairs;

    event AreAllPairsAvailableChanged(bool status);
    event AvailablePairChanged(
        address indexed taIn,
        address indexed taOut,
        bool status
    );

    function setAreAllPairsAvailable(
        bool _status
    ) external onlyRole(OPERATION_MANAGER_ROLE) {
        areAllPairsAvailable = _status;

        emit AreAllPairsAvailableChanged(_status);
    }
    function setAvailablePair(
        address _taIn,
        address _taOut,
        bool _status
    ) external onlyRole(OPERATION_MANAGER_ROLE) {
        bytes32 pairKey = keccak256(abi.encodePacked(_taIn, _taOut));
        availablePairs[pairKey] = _status;

        emit AvailablePairChanged(_taIn, _taOut, _status);
    }

    function isAvailablePair(
        address _taIn,
        address _taOut
    ) public view returns (bool) {
        if (_taIn == _taOut) {
            return false;
        }
        if (areAllPairsAvailable) {
            return true;
        }
        bytes32 pairKey = keccak256(abi.encodePacked(_taIn, _taOut));
        return availablePairs[pairKey];
    }

    error PairNotAvailable(address tokenAddressIn, address tokenAddressOut);
    modifier onlyAvailablePair(address _taIn, address _taOut) {
        if (!isAvailablePair(_taIn, _taOut))
            revert PairNotAvailable(_taIn, _taOut);
        _;
    }

    // ====================
    // Roles
    // ====================
    // 0x261b87b2321a08d52f3b3ee0167bc0ecb9d54938405960f6cfb55fe47cab3c0e;
    bytes32 public constant OPERATION_MANAGER_ROLE =
        keccak256("OPERATION_MANAGER_ROLE");

    // 0x8429d542926e6695b59ac6fbdcd9b37e8b1aeb757afab06ab60b1bb5878c3b49;
    bytes32 public constant WHITELISTED_ROLE = keccak256("WHITELISTED_ROLE");

    // 0xb1fadd3142ab2ad7f1337ea4d97112bcc8337fc11ce5b20cb04ad038adf99819;
    bytes32 public constant ASSET_MANAGER_ROLE =
        keccak256("ASSET_MANAGER_ROLE");

    uint256 public constant BIAS_POINT_DENOMINATOR = 10000;

    // ====================
    // Fee management
    // ====================
    uint256 public feeBps = 0; // in basis points (bps), ex) 1% = 100 bps
    mapping(address => uint256) public cumulatedFees;

    error FeeTooHigh(uint256 attemptedFeeBps);
    event FeeBpsChanged(uint256 oldFeeBps, uint256 newFeeBps);

    // @notice FeeBps should be less than 100%
    function setFeeBps(
        uint256 _newFeeBps
    ) external onlyRole(ASSET_MANAGER_ROLE) {
        if (_newFeeBps >= BIAS_POINT_DENOMINATOR) {
            revert FeeTooHigh(_newFeeBps);
        }
        uint256 oldFeeBps = feeBps;
        feeBps = _newFeeBps;
        emit FeeBpsChanged(oldFeeBps, _newFeeBps);
    }

    // ====================
    // Whitelist Management
    // ====================
    bool public isWhitelistActive = true;

    event WhitelistStatusChanged(bool status);

    // @notice If the status is false, the whitelist check will be skipped and anyone can call the issue function. If the status is true, only whitelisted addresses can be the recipient.
    function setWhitelistStatus(
        bool _status
    ) external onlyRole(OPERATION_MANAGER_ROLE) {
        if (isWhitelistActive != _status) {
            isWhitelistActive = _status;
            emit WhitelistStatusChanged(_status);
        } else {
            revert NothingChanged();
        }
    }

    event WhitelistSet(address indexed walletAddress, bool status);
    function setWhitelistAddress(
        address _addr,
        bool _status
    ) external onlyRole(OPERATION_MANAGER_ROLE) {
        if (hasRole(WHITELISTED_ROLE, _addr) != _status) {
            if (_status) {
                grantRole(WHITELISTED_ROLE, _addr); // Only OPERATION_MANAGER_ROLE can call this function, as it's the admin of WHITELISTED_ROLE
            } else {
                revokeRole(WHITELISTED_ROLE, _addr); // Only OPERATION_MANAGER_ROLE can call this function, as it's the admin of WHITELISTED_ROLE
            }
            emit WhitelistSet(_addr, _status);
        } else {
            revert NothingChanged();
        }
    }

    error NotWhitelisted(address walletAddress);
    function checkIsWhitelisted(address walletAddress) internal view {
        if (isWhitelistActive && !hasRole(WHITELISTED_ROLE, walletAddress)) {
            revert NotWhitelisted(walletAddress);
        }
    }

    // ====================
    // Pause Management
    // ====================
    bool public isPaused = false;
    event PauseStatusChanged(bool status);
    function setPauseStatus(
        bool _status
    ) external onlyRole(OPERATION_MANAGER_ROLE) {
        if (isPaused != _status) {
            isPaused = _status;
            emit PauseStatusChanged(_status);
        } else {
            revert NothingChanged();
        }
    }

    error ContractPaused();
    modifier whenNotPaused() {
        if (isPaused) {
            revert ContractPaused();
        }
        _;
    }

    // ====================
    // Issue Logic
    // ====================
    struct QuoteData {
        uint256 amtIn;
        uint256 amtOut;
        uint256 fee;
        uint256 exRateIn;
        uint256 exRateOut;
    }

    error InvalidExchangeRate();
    // @param _amtOut should apply retainingDecimals truncation and fee deduction. : User should receive "_amtOut" or more, but not less.
    function getAmountIn(
        address _taIn,
        address _taOut,
        uint256 _amtOut, // Desired token amount to receive, after fee deduction
        uint256 _exRateIn, // Exchange rate for the input token, should be 8-decimal value.
        uint256 _exRateOut, // Exchange rate for the output token, should be 8-decimal value.
        uint256 _retainingDecimals
    ) public view returns (QuoteData memory data) {
        if (_exRateIn == 0 || _exRateOut == 0) {
            revert InvalidExchangeRate();
        }

        uint256 dIn = uint256(IERC20Metadata(_taIn).decimals());
        uint256 dOut = uint256(IERC20Metadata(_taOut).decimals());

        // Algebraic inverse of:
        // rawAmtOut ~= ((_amtIn - fee) * 10**dOut * _exRateIn) / (10**dIn * _exRateOut)
        //
        // and approximating:
        // (_amtIn - fee) ~= _amtIn * (DENOM - feeBps) / DENOM
        //
        // => amtIn ~= (_amtOut * 10**dIn * _exRateOut * DENOM)
        //           / (10**dOut * _exRateIn * (DENOM - feeBps))
        uint256 scaleIn = 10 ** dIn;
        uint256 scaleOut = 10 ** dOut;

        uint256 step = 10 **
            (dOut > _retainingDecimals ? dOut - _retainingDecimals : 0);

        if (_amtOut % step != 0) {
            revert InvalidAmountOut();
        }

        // feeBps is verified to be less than 100% in setFeeBps(), so feeDenom cannot be less or equal to zero.
        uint256 feeDenom = BIAS_POINT_DENOMINATOR - feeBps;

        uint256 numerator = _amtOut;
        numerator = Math.mulDiv(numerator, scaleIn, 1);
        numerator = Math.mulDiv(numerator, _exRateOut, 1);
        numerator = Math.mulDiv(numerator, BIAS_POINT_DENOMINATOR, 1);

        uint256 denominator = scaleOut;
        denominator = Math.mulDiv(denominator, _exRateIn, 1);
        denominator = Math.mulDiv(denominator, feeDenom, 1);

        uint256 approxAmtIn = numerator / denominator;
        if (numerator % denominator != 0) {
            approxAmtIn += 1;
        }

        // Verification step:
        // Because getAmountOut() includes floor rounding and retainingDecimals truncation,
        // the algebraic inverse may still be slightly low. Revert if the calculated input
        // does not produce at least the requested output.
        QuoteData memory q = getAmountOut(
            _taIn,
            _taOut,
            approxAmtIn,
            _exRateIn,
            _exRateOut,
            _retainingDecimals
        );

        if (q.amtOut < _amtOut) {
            revert InvalidAmountOut();
        }

        return q;
    }

    function getAmountOut(
        address _taIn,
        address _taOut,
        uint256 _amtIn, // Token amount to pay, before fee deduction
        uint256 _exRateIn, // Exchange rate for the input token, should be 8-decimal value.
        uint256 _exRateOut, // Exchange rate for the output token, should be 8-decimal value.
        uint256 _retainingDecimals
    ) public view returns (QuoteData memory) {
        if (_exRateIn == 0 || _exRateOut == 0) {
            revert InvalidExchangeRate();
        }

        uint256 fee = Math.mulDiv(_amtIn, feeBps, BIAS_POINT_DENOMINATOR);
        uint256 amtInAfterFee = _amtIn - fee;

        uint256 dIn = uint256(IERC20Metadata(_taIn).decimals());
        uint256 dOut = uint256(IERC20Metadata(_taOut).decimals());

        // The full calculation is: ((_amtIn - fee) * 10 ** dOut * _exRateIn) / (10 ** dIn * _exRateOut)
        uint256 rawAmtOut = Math.mulDiv(
            Math.mulDiv(amtInAfterFee, 10 ** dOut, 1),
            _exRateIn,
            _exRateOut * (10 ** dIn)
        );

        uint256 retainingDecimal = (
            dOut > _retainingDecimals ? dOut - _retainingDecimals : 0
        );

        uint256 _amountOut = rawAmtOut - (rawAmtOut % (10 ** retainingDecimal));

        return
            QuoteData({
                amtIn: _amtIn,
                amtOut: _amountOut,
                fee: fee,
                exRateIn: _exRateIn,
                exRateOut: _exRateOut
            });
    }

    function issue(
        address _taIn, // token address to pay
        address _taOut, // token address to receive
        uint256 _amtIn, // amount to pay
        uint256 _amtOutMin, // the minimum amount out that the user can receive, used for slippage control
        uint256 _exRateIn, // _exRateIn should be 8-decimal value
        uint256 _exRateOut, // _exRateOut should be 8-decimal value
        uint256 _retainingDecimals, // number of decimals to retain for the output amount
        address owner, // owner of the tokens to pay, who made the permit signature
        uint256 deadline, // deadline for the permit signature
        uint8 v, // v, r, s are the parameters for the permit signature
        bytes32 r,
        bytes32 s
    )
        external
        whenNotPaused
        onlyAvailablePair(_taIn, _taOut)
        onlyRole(OPERATION_MANAGER_ROLE)
        nonReentrant
    {
        // Validation 0. Parameter check: non-zero amount
        if (_amtIn == 0 || _amtOutMin == 0) {
            revert InvalidAmount();
        }

        // Validation 0. Parameter check: exrate cannot be zero
        if (_exRateIn == 0 || _exRateOut == 0) {
            revert InvalidExchangeRate();
        }

        // Validation 1. Check if the owner is whitelisted (if whitelist is active)
        checkIsWhitelisted(owner);

        // Validation 2. Check if the calculation is right
        QuoteData memory quoteData = getAmountOut(
            _taIn,
            _taOut,
            _amtIn,
            _exRateIn,
            _exRateOut,
            _retainingDecimals
        );

        {
            // Validation 3. Check if the amount out is not zero
            if (quoteData.amtOut == 0) {
                revert InvalidAmount();
            }

            // Validation 4. Check if the amount out is within the slippage range
            if (quoteData.amtOut < _amtOutMin) {
                revert SlippageExceeded(quoteData.amtOut, _amtOutMin);
            }
            // Validation 5. Check if the contract has enough reserve of the output token
            uint256 reserveOut = getReserve(_taOut);
            if (quoteData.amtOut > reserveOut) {
                revert InsufficientReserve(
                    _taOut,
                    quoteData.amtOut,
                    reserveOut
                );
            }
        }

        if (IERC20(_taIn).allowance(owner, address(this)) < _amtIn) {
            // 1. Call Permit to increase allowance for the token transfer
            try
                IERC20Permit(_taIn).permit(
                    owner,
                    address(this),
                    _amtIn,
                    deadline,
                    v,
                    r,
                    s
                )
            {
                // Permit successful, allowance should be updated
            } catch {
                // permit may have been front-run or otherwise failed
                // anyway, continue and let the transferFrom fail if allowance is insufficient
            }
        }

        // 2. Transfer the tokens from the user to the contract
        uint256 balanceBefore = IERC20(_taIn).balanceOf(address(this));
        IERC20(_taIn).safeTransferFrom(owner, address(this), _amtIn);
        uint256 balanceAfter = IERC20(_taIn).balanceOf(address(this));
        if ((balanceAfter - balanceBefore) != _amtIn) {
            // balanceAfter should be greater than balanceBefore
            revert NotAllowedFeeOnTransfer(_taIn);
        }

        // 3. Transfer the tokens from the contract to the user, after calculating the fee
        balanceBefore = IERC20(_taOut).balanceOf(address(this));
        IERC20(_taOut).safeTransfer(owner, quoteData.amtOut);
        balanceAfter = IERC20(_taOut).balanceOf(address(this));
        if ((balanceBefore - balanceAfter) != quoteData.amtOut) {
            // balanceAfter should be less than balanceBefore
            revert NotAllowedFeeOnTransfer(_taOut);
        }
        // 4. Update the cumulated fees
        cumulatedFees[_taIn] += quoteData.fee;

        emit tokenIssued(
            _taIn,
            _taOut,
            owner,
            _amtIn,
            quoteData.amtOut,
            quoteData.fee,
            _exRateIn,
            _exRateOut
        );
    }

    event tokenIssued(
        address indexed tokenAddressIn,
        address indexed tokenAddressOut,
        address indexed recipient,
        uint256 amountIn,
        uint256 amountOut,
        uint256 fee,
        uint256 rateIn,
        uint256 rateOut
    );

    error InsufficientReserve(
        address tokenAddress,
        uint256 requested,
        uint256 available
    );

    error SlippageExceeded(uint256 amountOut, uint256 amountOutMin);
    error InvalidAmount();
    error InvalidAmountOut();

    // ====================
    // Reserve and Fee Management
    // ====================
    function getReserve(address _ta) public view returns (uint256) {
        uint256 balance = IERC20(_ta).balanceOf(address(this));
        uint256 fee = cumulatedFees[_ta];
        // When balance is less than fee, reserve is considered as zero.
        // If the token balance is less than the recorded fees, the available reserve is treated as zero.
        // This should only occur under exceptional accounting mismatch scenarios.
        if (balance <= fee) {
            return 0;
        } else return (balance - fee);
    }

    event ReserveWithdrawn(
        address indexed tokenAddress,
        address indexed recipient,
        uint256 amount
    );
    function withdrawReserve(
        address _ta, // token address
        address _to, // recipient address
        uint256 _amt // amount to withdraw
    ) external onlyRole(ASSET_MANAGER_ROLE) {
        uint256 reserve = getReserve(_ta);
        if (_amt > reserve) revert InsufficientReserve(_ta, _amt, reserve);
        IERC20(_ta).safeTransfer(_to, _amt);

        emit ReserveWithdrawn(_ta, _to, _amt);
    }

    event FeesWithdrawn(
        address indexed tokenAddress,
        address indexed recipient,
        uint256 amount
    );
    error InsufficientCumulatedFees(
        address tokenAddress,
        uint256 requested,
        uint256 available
    );
    function withdrawFees(
        address _ta, // token address
        address _to, // recipient address
        uint256 _amt // amount to withdraw
    ) external onlyRole(ASSET_MANAGER_ROLE) nonReentrant {
        uint256 feeAmt = cumulatedFees[_ta];
        if (_amt > feeAmt) revert InsufficientCumulatedFees(_ta, _amt, feeAmt);

        uint256 balanceBefore = IERC20(_ta).balanceOf(address(this));

        IERC20(_ta).safeTransfer(_to, _amt);

        uint256 balanceAfter = IERC20(_ta).balanceOf(address(this));
        uint256 balanceDelta = balanceBefore - balanceAfter;

        if (balanceDelta != _amt) {
            // balanceAfter should be less than balanceBefore
            revert NotAllowedFeeOnTransfer(_ta);
        }

        // Reject fee-on-transfer or other non-standard token behaviors
        // reentrancy guard is added for the safety of this step
        cumulatedFees[_ta] = feeAmt - _amt;

        emit FeesWithdrawn(_ta, _to, _amt);
    }

    event EmergencyFeeWithdrawal(
        address indexed tokenAddress,
        address indexed recipient,
        uint256 cumulatedFeeAmount,
        uint256 balanceDelta
    );
    // @notice Emergency-only function to withdraw all accumulated fees for a token and reset cumulatedFees to zero.
    // @dev This function is intended for exceptional cases where normal withdrawFees() cannot be used.
    //      It intentionally does not enforce balance-delta equality and resets fee accounting to zero.
    //      The emitted balanceDelta should be reviewed off-chain for monitoring and reconciliation.
    function emergencyWithdrawFee(
        address _ta,
        address _to
    ) external onlyRole(DEFAULT_ADMIN_ROLE) nonReentrant {
        uint256 feeAmt = cumulatedFees[_ta];

        cumulatedFees[_ta] = 0;

        uint256 balanceBefore = (IERC20(_ta).balanceOf(address(this)));
        IERC20(_ta).safeTransfer(_to, feeAmt);
        uint256 balanceAfter = (IERC20(_ta).balanceOf(address(this)));

        // In emergency withdrawal, we do not revert even if the balance delta does not match the fee amount, but we emit the actual balance delta for monitoring purposes.
        uint256 balanceDelta = balanceBefore > balanceAfter
            ? balanceBefore - balanceAfter
            : 0;

        emit EmergencyFeeWithdrawal(_ta, _to, feeAmt, balanceDelta);
    }

    // ====================
    // Global Error
    // ====================
    error NothingChanged();
    error NotAllowedFeeOnTransfer(address tokenAddress);
}

contracts/Mockups/MockERC20Permit.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";

contract MockERC20Permit is ERC20Permit {
    constructor(
        string memory name,
        string memory symbol,
        uint8 _decimals
    ) ERC20(name, symbol) ERC20Permit(name) {
        tokenDecimals = _decimals;
        _mint(msg.sender, 1000000 * 10 ** tokenDecimals);
    }
    uint8 private tokenDecimals;

    function decimals() public view override returns (uint8) {
        return tokenDecimals;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

contracts/RedeemLock/RedeemLock.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";

interface IRedeemToken is IERC20 {
    function burn(uint256 amount) external;
}

contract RedeemLock is AccessControl {
    enum OrderStatus {
        Pending,
        Stocked,
        Redeemed,
        Burned,
        Cancelled
    }

    function statusToString(
        OrderStatus status
    ) public pure returns (string memory) {
        if (status == OrderStatus.Pending) return "Pending";
        if (status == OrderStatus.Stocked) return "Stocked";
        if (status == OrderStatus.Redeemed) return "Redeemed";
        if (status == OrderStatus.Burned) return "Burned";
        if (status == OrderStatus.Cancelled) return "Cancelled";
        return "Unknown";
    }

    bytes32 public constant REDEEM_MANAGER_ROLE =
        keccak256("REDEEM_MANAGER_ROLE");
    bytes32 public constant ASSET_MANAGER_ROLE =
        keccak256("ASSET_MANAGER_ROLE");

    IRedeemToken public immutable redeemToken;

    constructor(address _redeemToken) {
        redeemToken = IRedeemToken(_redeemToken);
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    uint256 public cumulatedCosts;

    struct OrderData {
        address user;
        uint256 goldWeight;
        uint256 extraCost;
        OrderStatus status;
    }

    mapping(address => uint256) internal userNonce;
    mapping(address => mapping(uint256 => bytes32)) public userOrders;
    mapping(bytes32 => OrderData) public orders;

    event RedeemLockCreated(
        bytes32 indexed orderId,
        address indexed user,
        uint256 goldWeight,
        uint256 extraCost,
        uint256 nonce
    );

    function getNonce(address _user) external view returns (uint256) {
        return userNonce[_user];
    }

    function redeemLock(
        uint256 _goldWeight,
        uint256 _extraCost,
        address _owner,
        uint256 _deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external onlyRole(REDEEM_MANAGER_ROLE) {
        uint256 nonce = userNonce[_owner];

        uint256 totalAmount = _goldWeight + _extraCost;

        if (redeemToken.allowance(_owner, address(this)) < totalAmount) {
            try
                IERC20Permit(address(redeemToken)).permit(
                    _owner,
                    address(this),
                    totalAmount,
                    _deadline,
                    v,
                    r,
                    s
                )
            {
                // Permit successful, allowance should be updated
            } catch {
                // permit may have been front-run or otherwise failed
                // anyway, continue and let the transferFrom fail if allowance is insufficient
            }
        }

        // If the permit succeeded, this transferFrom should work;
        // if it failed, it will revert here due to insufficient allowance
        redeemToken.transferFrom(_owner, address(this), totalAmount);

        bytes32 orderId = keccak256(
            abi.encodePacked(
                _owner,
                _goldWeight,
                _extraCost,
                nonce,
                block.timestamp
            )
        );

        orders[orderId] = OrderData({
            user: _owner,
            goldWeight: _goldWeight,
            extraCost: _extraCost,
            status: OrderStatus.Pending
        });

        emit RedeemLockCreated(orderId, _owner, _goldWeight, _extraCost, nonce);

        userOrders[_owner][nonce] = orderId;
        userNonce[_owner]++;
    }

    error InvalidOrderStatus(bytes32 orderId);

    function updateOrderStatus(bytes32 orderId, OrderStatus status) internal {
        orders[orderId].status = status;
    }

    event OrderStocked(bytes32 indexed orderId);

    function stockOrder(
        bytes32 orderId
    ) external onlyRole(REDEEM_MANAGER_ROLE) {
        OrderData storage order = orders[orderId];
        if (order.user == address(0)) revert InvalidOrderStatus(orderId);

        if (order.status != OrderStatus.Pending) {
            revert InvalidOrderStatus(orderId);
        }

        updateOrderStatus(orderId, OrderStatus.Stocked);

        emit OrderStocked(orderId);
    }

    event RedeemExecuted(bytes32 indexed orderId, address indexed user);

    function redeemOrder(
        bytes32 orderId
    ) external onlyRole(REDEEM_MANAGER_ROLE) {
        OrderData storage order = orders[orderId];
        if (order.user == address(0)) revert InvalidOrderStatus(orderId);

        if (order.status != OrderStatus.Stocked) {
            revert InvalidOrderStatus(orderId);
        }

        updateOrderStatus(orderId, OrderStatus.Redeemed);

        emit RedeemExecuted(orderId, order.user);
    }

    event RedeemBurned(
        bytes32 indexed orderId,
        address indexed user,
        uint256 goldWeight,
        uint256 extraCost
    );

    function redeemBurn(
        bytes32 orderId
    ) external onlyRole(REDEEM_MANAGER_ROLE) {
        OrderData storage order = orders[orderId];
        if (order.user == address(0)) revert InvalidOrderStatus(orderId);

        if (order.status != OrderStatus.Redeemed)
            revert InvalidOrderStatus(orderId);

        updateOrderStatus(orderId, OrderStatus.Burned);

        redeemToken.burn(order.goldWeight);
        cumulatedCosts += order.extraCost;

        emit RedeemBurned(
            orderId,
            order.user,
            order.goldWeight,
            order.extraCost
        );
    }

    error NotOrderOwner(bytes32 orderId);

    event RedeemRequestCancelled(bytes32 indexed orderId, address indexed user);

    // @notice : User can cancel the redeem request and get refund when the order is pending
    function cancelRedeemRequest(bytes32 orderId) external {
        if (orders[orderId].user != msg.sender) revert NotOrderOwner(orderId);

        if (orders[orderId].status != OrderStatus.Pending)
            revert InvalidOrderStatus(orderId);

        updateOrderStatus(orderId, OrderStatus.Cancelled);

        uint256 refundAmount = orders[orderId].goldWeight +
            orders[orderId].extraCost;

        // Clear the order data to prevent future confusion, double-refunds
        orders[orderId].goldWeight = 0;
        orders[orderId].extraCost = 0;

        redeemToken.transfer(msg.sender, refundAmount);

        emit RedeemRequestCancelled(orderId, orders[orderId].user);
    }

    event RedeemCancelled(
        bytes32 indexed orderId,
        address indexed orderOwner,
        string reason
    );

    // @notice : If the order status was changed to "Redeemed" by mistake, the ASSET_MANAGER_ROLE can cancel the redeem order
    // @notice : ASSET_MANAGER_ROLE is managed by Multisig, so off-chain discussion and agreement is required before calling this function
    // @params _reason The reason for cancellation, which will be emitted in the RedeemCancelled event
    function cancelRedeemedOrder(
        bytes32 orderId,
        string memory _reason
    ) external onlyRole(ASSET_MANAGER_ROLE) {
        OrderStatus currentStatus = (orders[orderId].status);
        if (currentStatus != OrderStatus.Redeemed) {
            revert InvalidOrderStatus(orderId);
        }

        updateOrderStatus(orderId, OrderStatus.Stocked);

        emit RedeemCancelled(orderId, orders[orderId].user, _reason);
    }

    event CostsWithdrawn(address indexed to, uint256 amount);
    function withdrawCosts(
        address to,
        uint256 amount
    ) external onlyRole(ASSET_MANAGER_ROLE) {
        require(amount <= cumulatedCosts, "Amount exceeds cumulated costs");
        cumulatedCosts -= amount;
        redeemToken.transfer(to, amount);

        emit CostsWithdrawn(to, amount);
    }
}
